try{paused=localStorage.getItem('wafiy-motion-paused')==='true'}catch{}
const running=new Map(),seen=new WeakSet(),pending=new Set();
const groups=[['.hero-copy>.eyebrow','up'],['.hero-copy>h1','up'],['.hero-role','up'],['.hero-copy>.sd','up'],['.hero-copy>.cta','up'],['.profile-panel','scale'],['.center-heading','up'],['.profile-card','left'],['.technical-card','right'],['.practice-card','left'],['.about-portrait','scale'],['.education-card','right'],['.experience-record','right'],['.sg>div:first-child','left'],['.section-heading','up'],['.project-toolbar','up'],['.acc .it','up'],['.contact-card','up']];
function stop(){cancelAnimationFrame(frame);frame=0;last=0}
function resize(){width=innerWidth;height=innerHeight;const dpr=Math.min(devicePixelRatio||1,1.5);canvas.width=Math.round(width*dpr);canvas.height=Math.round(height*dpr);ctx?.setTransform(dpr,0,0,dpr,0,0);particles=Array.from({length:small.matches?22:58},()=>({x:Math.random()*width,y:Math.random()*height,size:Math.random()<.12?2.5:1,pace:5+Math.random()*9,phase:Math.random()*Math.PI*2}));}
function draw(time){frame=0;if(!enabled||document.hidden||!ctx)return;frame=requestAnimationFrame(draw);if(last&&time-last<32)return;const dt=last?Math.min((time-last)/1000,.06):0;last=time;ctx.clearRect(0,0,width,height);ctx.fillStyle=root.dataset.theme==='dark'?'#E2EBC7':'#FFFFFF';for(const p of particles){p.y-=p.pace*dt;p.x+=Math.sin(time*.00015+p.phase)*dt*3;if(p.y< -4)p.y=height+4;if(p.x< -4)p.x=width+4;if(p.x>width+4)p.x=-4;ctx.globalAlpha=.18+.42*(.5+.5*Math.sin(time*.0005+p.phase));ctx.fillRect(p.x,p.y,p.size,p.size)}ctx.globalAlpha=1;}
