function enter(element){pending.delete(element);observer?.unobserve(element);if(seen.has(element))return;seen.add(element);if(!enabled||!element.animate)return;const kind=element.dataset.enter;const from={left:'perspective(1000px) translateX(-26px) rotateY(3deg)',right:'perspective(1000px) translateX(26px) rotateY(-3deg)',scale:'scale(.96)',up:'perspective(1000px) translateY(28px) rotateX(2deg)'}[kind]||'translateY(24px)';const animation=element.animate([{opacity:0,transform:from},{opacity:1,transform:'none'}],{duration:720,delay:Number(element.dataset.delay)||0,easing:'cubic-bezier(.16,1,.3,1)',fill:'backwards'});running.set(element,animation);animation.finished.then(()=>{if(running.get(element)===animation)running.delete(element)},()=>{if(running.get(element)===animation)running.delete(element)});}
