function cards(){for(const e of pending)if(!e.isConnected){observer?.unobserve(e);pending.delete(e)}for(const [e,a]of running)if(!e.isConnected){a.cancel();running.delete(e)}document.querySelectorAll('#grid .card').forEach((e,i)=>register(e,'up',i%3));}
function sync(){enabled=!paused&&!reduce.matches;root.dataset.motion=enabled?'on':'off';button.disabled=reduce.matches;button.setAttribute('aria-pressed',String(!enabled));button.textContent=reduce.matches?'Reduced motion enabled':enabled?'Pause animations':'Resume animations';stop();if(!enabled){ctx?.clearRect(0,0,width,height);for(const a of running.values())a.cancel();running.clear()}start();document.dispatchEvent(new CustomEvent('portfolio:motionchange'));}
button.addEventListener('click',()=>{paused=!paused;try{localStorage.setItem('wafiy-motion-paused',String(paused))}catch{}sync()});reduce.addEventListener('change',sync);
document.addEventListener('visibilitychange',()=>{root.classList.toggle('page-hidden',document.hidden);if(document.hidden){stop();for(const a of running.values())a.pause()}else{for(const a of running.values())a.play();start()}});
document.addEventListener('focusin',e=>{for(const [element,a]of running)if(element.contains(e.target)){a.cancel();running.delete(element)}});
